Dataspatium.assets.register("presets/api/eurostat.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"eurostat\",\n  \"name\": \"Eurostat\",\n  \"publisher\": \"Eurostat (Europeiska kommissionen)\",\n  \"description\": \"EU-statistik per land och region. Ange datamängdens kod (till exempel demo_pjan för befolkning eller nama_10_gdp för BNP) och filtrera på länder och period. Koder och dimensioner hittar du i Eurostats Data browser.\",\n  \"docs\": \"https://wikis.ec.europa.eu/display/EUROSTATHELP/API+-+Getting+started+with+statistics+API\",\n  \"license\": { \"name\": \"CC BY 4.0\", \"url\": \"https://creativecommons.org/licenses/by/4.0/\" },\n  \"level\": 1,\n  \"baseUrl\": \"https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 10, \"perSeconds\": 5 },\n  \"endpoints\": [\n    {\n      \"id\": \"data\",\n      \"name\": \"Hämta datamängd\",\n      \"description\": \"Högst 50 000 celler per anrop. Utan filter kan stora datamängder avvisas av tjänsten; välj då länder och period.\",\n      \"method\": \"GET\",\n      \"path\": \"/{dataset}\",\n      \"params\": [\n        { \"name\": \"dataset\", \"in\": \"path\", \"label\": \"Datamängdens kod\", \"type\": \"string\", \"required\": true, \"example\": \"demo_pjan\" },\n        { \"name\": \"geo\", \"in\": \"query\", \"label\": \"Länder eller regioner (geo-koder)\", \"type\": \"multi\", \"style\": \"repeat\", \"example\": \"SE,DK,FI,NO\" },\n        { \"name\": \"sinceTimePeriod\", \"in\": \"query\", \"label\": \"Från period\", \"type\": \"string\", \"example\": \"2015\" },\n        { \"name\": \"untilTimePeriod\", \"in\": \"query\", \"label\": \"Till period\", \"type\": \"string\" },\n        { \"name\": \"lastTimePeriod\", \"in\": \"query\", \"label\": \"Bara de senaste n perioderna\", \"type\": \"number\" },\n        { \"name\": \"filters\", \"in\": \"query\", \"label\": \"Fler filter\", \"type\": \"querylines\", \"help\": \"En per rad som dimension=kod, till exempel sex=T eller age=TOTAL.\", \"example\": \"sex=T\" },\n        { \"name\": \"lang\", \"in\": \"query\", \"label\": \"Språk för etiketter\", \"type\": \"enum\", \"default\": \"EN\", \"options\": [{ \"value\": \"EN\", \"label\": \"Engelska\" }, { \"value\": \"DE\", \"label\": \"Tyska\" }, { \"value\": \"FR\", \"label\": \"Franska\" }] },\n        { \"name\": \"format\", \"in\": \"query\", \"type\": \"string\", \"default\": \"JSON\", \"hidden\": true }\n      ],\n      \"response\": { \"format\": \"jsonstat\" },\n      \"dataset\": { \"name\": \"Eurostat {dataset}\" }\n    }\n  ]\n}\n");
